1	/**
2	 * Human-facing read-only `/components` command over the component registry.
3	 * @module @deepseek-ai/dsh-command-components
4	 */
5	
6	import type { Context } from '@deepseek-ai/cordis'
7	import type { CommandInvocation, CommandResult } from '@deepseek-ai/dsh-commands'
8	import type { ComponentDescriptor } from '@deepseek-ai/dsh-components'
9	
10	export const name = 'command-components'
11	export const inject = ['commands', 'components']
12	
13	const USAGE = 'Usage: /components'
14	
15	/** Render one component as a single inventory line. */
16	function renderComponent(component: ComponentDescriptor): string {
17	  const facets: string[] = [component.provenance]
18	  if (component.lineage !== undefined) facets.push(`from ${component.lineage}`)
19	  if (component.members !== undefined) facets.push(`${component.members.length} members`)
20	  if (component.invoke !== undefined) facets.push(`via ${component.invoke.tool}`)
21	  return `- ${component.id}: ${component.description} · ${facets.join(' · ')}`
22	}
23	
24	/** Render the inventory grouped by kind in first-seen order. */
25	function renderInventory(components: readonly ComponentDescriptor[]): CommandResult {
26	  const byKind = new Map<string, ComponentDescriptor[]>()
27	  for (const component of components) {
28	    const group = byKind.get(component.kind)
29	    if (group === undefined) byKind.set(component.kind, [component])
30	    else group.push(component)
31	  }
32	  const lines = [`Components (${components.length})`]
33	  for (const [kind, group] of byKind) {
34	    lines.push(`${kind} (${group.length}):`, ...group.map(renderComponent))
35	  }
36	  return { kind: 'success', text: lines.join('\n') }
37	}
38	
39	/** Execute the read-only inventory view through the registry that owns it. */
40	function executeComponentsCommand(ctx: Context, invocation: CommandInvocation): CommandResult {
41	  if (invocation.rawInput.trim().length !== 0) {
42	    return { kind: 'error', text: `The components command takes no arguments. ${USAGE}` }
43	  }
44	  const components = ctx.components.list()
45	  return components.length === 0
46	    ? { kind: 'success', text: `No components are registered in this composition.\n${USAGE}` }
47	    : renderInventory(components)
48	}
49	
50	/** Register the read-only `/components` inventory command for every composed command adapter. */
51	export function apply(ctx: Context): void {
52	  ctx.commands.register({
53	    name: 'components',
54	    description: 'view every addressable component in this composition, grouped by kind',
55	    handler: invocation => executeComponentsCommand(ctx, invocation),
56	  })
57	}
